      { name: "checkpoints land in order", code: "_, marks = fn(45)\nvalues = [marks[m] for m in sorted(marks)]\nassert values == sorted(values)", hidden: false },
      { name: "invalid arguments are rejected", code: "for args in ((0,), (45, (1.5,))):\n    try:\n        fn(*args)\n        raise AssertionError('should have raised')\n    except ValueError:\n        pass", hidden: true }
